import pytest
import unittest
from candidate import decode_shift

class TestDecodeShift(unittest.TestCase):

    def test_decode_shift_empty_string(self):
        self.assertEqual(decode_shift(""), "")

    def test_decode_shift_single_character(self):
        self.assertEqual(decode_shift("a"), "v")

    def test_decode_shift_two_characters(self):
        self.assertEqual(decode_shift("bc"), "ab")

    def test_decode_shift_uppercase(self):
        self.assertEqual(decode_shift("AZ"), "VW")

    def test_decode_shift_mixed_case(self):
        self.assertEqual(decode_shift("aBc"), "vUb")

    def test_decode_shift_repeated_characters(self):
        self.assertEqual(decode_shift("aaAA"), "ccCC")

    def test_decode_shift_with_non_alphabetical_characters(self):
        self.assertEqual(decode_shift("a1b2c3"), "v1x2y3")

    def test_decode_shift_with_spaces(self):
        self.assertEqual(decode_shift(" hello "), "cewwww "

    def test_decode_shift_with_numbers(self):
        self.assertEqual(decode_shift("a1b2c3"), "v1x2y3")

    def test_decode_shift_with_special_characters(self):
        self.assertEqual(decode_shift("!@# $% ^&"), "fghj kl")

    def test_decode_shift_with_long_string(self):
        self.assertEqual(decode_shift("the quick brown fox jumps over the lazy dog"), "ymnx vzlmg zgyb qjgt gkc")

if __name__ == "__main__":
    unittest.main()
